<?php
declare(strict_types=1);
namespace App\Interface\Http\Review\Controller;
use App\Application\Identity\DTO\Request\AccessTokenRequestDto;use App\Application\Identity\Service\AuthService;use App\Application\Review\DTO\Request\CobitGameAnswersRequestDto;use App\Application\Review\Service\CobitGameService;use App\Domain\Identity\Exception\UnavailableUserException;use App\Infrastructure\Http\ApiResponseFactory;use Psr\Http\Message\ResponseInterface;use Psr\Http\Message\ServerRequestInterface;
final class CobitGameController { public function __construct(private AuthService $auth,private CobitGameService $service,private ApiResponseFactory $responses){} public function exercise(ServerRequestInterface $r,ResponseInterface $p,AccessTokenRequestDto $access):ResponseInterface{try{$this->auth->currentUser($access);return $this->responses->success($p,$this->service->exercise(),(string)$r->getAttribute('request_id'));}catch(UnavailableUserException){return $this->responses->problem($p,'UNAUTHENTICATED','Credenciais inválidas ou expiradas.',401,(string)$r->getAttribute('request_id'));}} public function evaluate(ServerRequestInterface $r,ResponseInterface $p,AccessTokenRequestDto $access,CobitGameAnswersRequestDto $input):ResponseInterface{try{$this->auth->currentUser($access);return $this->responses->success($p,$this->service->evaluate($input),(string)$r->getAttribute('request_id'));}catch(\InvalidArgumentException){return $this->responses->problem($p,'VALIDATION_FAILED','Envie uma associação para cada processo.',422,(string)$r->getAttribute('request_id'));}catch(UnavailableUserException){return $this->responses->problem($p,'UNAUTHENTICATED','Credenciais inválidas ou expiradas.',401,(string)$r->getAttribute('request_id'));}} }
